/**
 * Spike C — LLM termination behavior verification
 *
 * Disposable spike test. Verifies whether the AI SDK's `generateText`
 * tool loop terminates as expected when an `execute()` returns
 * `{ modalOpened: true }` — which is the architecture we'd use
 * to short-circuit the LLM after opening a Slack modal.
 *
 * Uses MockLanguageModelV3 (no live API key needed).
 */

import { describe, it, expect } from "vitest";
import { generateText, stepCountIs, tool, type StopCondition } from "ai";
import { MockLanguageModelV3 } from "ai/test";
import { z } from "zod";

/**
 * Build a synthetic tool that mirrors what `create_week_item` would do
 * after a modal-intercept refactor: returns `{ modalOpened: true, proposalId }`.
 */
function buildModalInterceptTool() {
  let executeCalls = 0;
  const t = tool({
    description: "Create a week item (intercepted to open a modal)",
    inputSchema: z.object({
      title: z.string(),
    }),
    execute: async ({ title }) => {
      executeCalls += 1;
      // Throwaway intercept — would normally call views.open + DB insert
      return { modalOpened: true, proposalId: `prop-${title}` };
    },
  });
  return { tool: t, getCalls: () => executeCalls };
}

/**
 * Build a mock language model that responds in a controlled, sequential way.
 * Pass an array of `LanguageModelV3GenerateResult`-like objects; the mock
 * returns them in order on each call.
 *
 * NOTE: MockLanguageModelV3.doGenerate uses `responses[doGenerateCalls.length]`
 * AFTER pushing, so the array is effectively 1-indexed. We work around this
 * by putting an unused sentinel at index 0.
 */
function buildSequentialModel(responses: Array<unknown>) {
  return new MockLanguageModelV3({
    doGenerate: [{ /* sentinel index 0 */ } as never, ...responses] as never,
  });
}

const baseUsage = { inputTokens: 10, outputTokens: 5, totalTokens: 15 };

/** Build a "model emits a tool call" response. */
function toolCallResponse(toolName: string, input: object, callId = "call_1") {
  return {
    content: [
      {
        type: "tool-call" as const,
        toolCallId: callId,
        toolName,
        input,
      },
    ],
    finishReason: "tool-calls" as const,
    usage: baseUsage,
    warnings: [],
  };
}

/** Build a "model emits final text" response. */
function textResponse(text: string) {
  return {
    content: [{ type: "text" as const, text }],
    finishReason: "stop" as const,
    usage: baseUsage,
    warnings: [],
  };
}

describe("Spike C — termination behavior", () => {
  it("BASELINE: stopWhen=stepCountIs(MAX) — LLM is RE-INVOKED after intercepted tool returns modalOpened:true (loop continues)", async () => {
    const { tool: interceptTool, getCalls } = buildModalInterceptTool();

    // Sequence:
    //  Step 1: model emits tool-call create_week_item
    //  Step 2: SDK runs execute() -> returns {modalOpened: true}
    //          SDK loops back, asks model again — model responds with text
    const model = buildSequentialModel([
      toolCallResponse("create_week_item", { title: "Daniel review Tuesday" }),
      textResponse("Modal opened — fill it in to confirm."),
    ]);

    const result = await generateText({
      model,
      tools: { create_week_item: interceptTool },
      prompt: "Add a week item: Daniel review Tuesday",
      stopWhen: stepCountIs(12),
    });

    // execute() ran exactly once
    expect(getCalls()).toBe(1);
    // The mock model was invoked TWICE — proving the loop re-prompted after the tool result
    expect(model.doGenerateCalls.length).toBe(2);
    // Two steps recorded
    expect(result.steps.length).toBe(2);
    // Last step has the modalOpened tool result
    const lastResults = result.steps.at(-1)?.toolResults ?? [];
    // toolResults are attached to the step that contained the tool call (step 1),
    // not the final step which is text-only.
    const allResults = result.steps.flatMap((s) => s.toolResults ?? []);
    expect(allResults.length).toBe(1);
    expect((allResults[0]?.output as { modalOpened?: boolean })?.modalOpened).toBe(true);
    // Sanity: the final text was produced by the second LLM call
    expect(result.text).toContain("Modal opened");
    // Document that lastResults could be empty depending on which step holds them
    void lastResults;
  });

  it("STRATEGY 1: custom stopWhen predicate on output.modalOpened terminates loop after exactly ONE LLM call", async () => {
    const { tool: interceptTool, getCalls } = buildModalInterceptTool();

    // Same model — but it only ever serves the FIRST response, because we'll stop after step 1.
    // Put a sentinel "should never be called" response at index 2 to assert.
    const model = buildSequentialModel([
      toolCallResponse("create_week_item", { title: "Daniel review Tuesday" }),
      // If this is reached, the predicate failed.
      textResponse("THIS SHOULD NEVER BE EMITTED"),
    ]);

    type ToolResultLike = { output?: { modalOpened?: boolean } };
    const stopOnModalOpen: StopCondition<Record<string, never>> = ({ steps }) => {
      const last = steps.at(-1);
      const results = (last?.toolResults ?? []) as ToolResultLike[];
      return results.some((r) => r.output?.modalOpened === true);
    };

    const result = await generateText({
      model,
      tools: { create_week_item: interceptTool },
      prompt: "Add a week item: Daniel review Tuesday",
      stopWhen: [stepCountIs(12), stopOnModalOpen],
    });

    expect(getCalls()).toBe(1);
    // CRITICAL: model invoked exactly ONCE — predicate stopped the loop before re-prompt
    expect(model.doGenerateCalls.length).toBe(1);
    expect(result.steps.length).toBe(1);
    // No final text was generated by the LLM (loop stopped before second call)
    expect(result.text).toBe("");
    // The bot wrapper must compose its own user-facing reply.
  });

  it("STRATEGY 2 SIM: per-conversation flag — second create_* call hard-rejects in execute()", async () => {
    let modalAlreadyOpenedThisConvo = false;
    let firstExecuteRan = false;
    let secondExecuteRan = false;

    const interceptTool = tool({
      description: "Create a week item (with per-convo guard)",
      inputSchema: z.object({ title: z.string() }),
      execute: async ({ title }) => {
        if (modalAlreadyOpenedThisConvo) {
          secondExecuteRan = true;
          return {
            error:
              "A modal has already been opened in this conversation. Tell the user to fill in the open modal or cancel it before creating another item.",
          };
        }
        firstExecuteRan = true;
        modalAlreadyOpenedThisConvo = true;
        return { modalOpened: true, proposalId: `prop-${title}` };
      },
    });

    // Model misbehaves: emits TWO create_week_item calls in sequence.
    const model = buildSequentialModel([
      toolCallResponse("create_week_item", { title: "First item" }, "call_1"),
      toolCallResponse("create_week_item", { title: "Second item" }, "call_2"),
      textResponse("Sorry, modal already open."),
    ]);

    const result = await generateText({
      model,
      tools: { create_week_item: interceptTool },
      prompt: "Add two week items",
      stopWhen: stepCountIs(12),
    });

    expect(firstExecuteRan).toBe(true);
    expect(secondExecuteRan).toBe(true);
    // Three model calls: tool1, tool2, final text
    expect(model.doGenerateCalls.length).toBe(3);
    // Both calls happened — Strategy 2 alone does NOT prevent the loop from re-running,
    // it only prevents the second execute() from corrupting state.
    const allResults = result.steps.flatMap((s) => s.toolResults ?? []);
    expect(allResults.length).toBe(2);
    expect((allResults[0]?.output as { modalOpened?: boolean })?.modalOpened).toBe(true);
    expect((allResults[1]?.output as { error?: string })?.error).toContain("already been opened");
  });

  it("STRATEGY 1 + 2 COMBINED: predicate stops loop AND flag would catch any race", async () => {
    let modalAlreadyOpenedThisConvo = false;
    let executeCount = 0;

    const interceptTool = tool({
      description: "Create a week item (combined safeguards)",
      inputSchema: z.object({ title: z.string() }),
      execute: async ({ title }) => {
        executeCount += 1;
        if (modalAlreadyOpenedThisConvo) {
          return { error: "Modal already open in this conversation." };
        }
        modalAlreadyOpenedThisConvo = true;
        return { modalOpened: true, proposalId: `prop-${title}` };
      },
    });

    type ToolResultLike = { output?: { modalOpened?: boolean } };
    const stopOnModalOpen: StopCondition<Record<string, never>> = ({ steps }) => {
      const last = steps.at(-1);
      const results = (last?.toolResults ?? []) as ToolResultLike[];
      return results.some((r) => r.output?.modalOpened === true);
    };

    const model = buildSequentialModel([
      toolCallResponse("create_week_item", { title: "Daniel review Tuesday" }),
      textResponse("THIS SHOULD NEVER BE EMITTED"),
    ]);

    await generateText({
      model,
      tools: { create_week_item: interceptTool },
      prompt: "Add a week item: Daniel review Tuesday",
      stopWhen: [stepCountIs(12), stopOnModalOpen],
    });

    expect(executeCount).toBe(1);
    expect(model.doGenerateCalls.length).toBe(1);
  });
});

